1	package sqlite
2	
3	import (
4		"context"
5		"database/sql"
6		"strings"
7	
8		"github.com/pkg/errors"
9	
10		storepb "github.com/usememos/memos/proto/gen/store"
11		"github.com/usememos/memos/store"
12	)
13	
14	const deleteUserBatchSize = 500
15	
16	type deleteUserMemoRef struct {
17		ID  int32
18		UID string
19	}
20	
21	type deleteUserTargetSet struct {
22		memos           []deleteUserMemoRef
23		attachments     []*store.Attachment
24		attachmentIDs   []int32
25		userSettingKeys []storepb.UserSetting_Key
26		inboxIDs        []int32
27	}
28	
29	func (d *DB) DeleteUser(ctx context.Context, delete *store.DeleteUser) (*store.DeleteUserResult, error) {
30		tx, err := d.db.BeginTx(ctx, nil)
31		if err != nil {
32			return nil, errors.Wrap(err, "failed to begin delete user transaction")
33		}
34		defer func() {
35			_ = tx.Rollback()
36		}()
37	
38		targets, err := collectDeleteUserTargets(ctx, tx, delete.ID)
39		if err != nil {
40			return nil, errors.Wrap(err, "failed to collect delete user targets")
41		}
42	
43		if err := deleteUserTargetsTx(ctx, tx, delete.ID, targets); err != nil {
44			return nil, errors.Wrap(err, "failed to delete user targets")
45		}
46	
47		if store.GetDeleteUserFailpoint(ctx) == store.DeleteUserFailpointBeforeCommit {
48			return nil, errors.New("delete user failpoint before commit")
49		}
50	
51		if err := tx.Commit(); err != nil {
52			return nil, errors.Wrap(err, "failed to commit delete user transaction")
53		}
54	
55		return &store.DeleteUserResult{
56			Attachments:     targets.attachments,
57			UserSettingKeys: targets.userSettingKeys,
58		}, nil
59	}
60	
61	func collectDeleteUserTargets(ctx context.Context, tx *sql.Tx, userID int32) (*deleteUserTargetSet, error) {
62		targets := &deleteUserTargetSet{}
63	
64		memos, err := listDeleteUserMemoTree(ctx, tx, userID)
65		if err != nil {
66			return nil, err
67		}
68		targets.memos = memos
69	
70		attachments, err := listDeleteUserAttachments(ctx, tx, userID, memoIDsFromRefs(memos))
71		if err != nil {
72			return nil, err
73		}
74		targets.attachments = attachments
75		targets.attachmentIDs = attachmentIDsFromList(attachments)
76	
77		userSettingKeys, err := listDeleteUserSettingKeys(ctx, tx, userID)
78		if err != nil {
79			return nil, err
80		}
81		targets.userSettingKeys = userSettingKeys
82	
83		inboxIDs, err := listDeleteUserInboxIDs(ctx, tx, userID, memoIDSetFromRefs(memos))
84		if err != nil {
85			return nil, err
86		}
87		targets.inboxIDs = inboxIDs
88	
89		return targets, nil
90	}
91	
92	func deleteUserTargetsTx(ctx context.Context, tx *sql.Tx, userID int32, targets *deleteUserTargetSet) error {
93		memoIDs := memoIDsFromRefs(targets.memos)
94		contentIDs := memoContentIDsFromRefs(targets.memos)
95	
96		if err := deleteReactionsByContentIDsTx(ctx, tx, contentIDs); err != nil {
97			return err
98		}
99		if err := deleteAttachmentsByIDsTx(ctx, tx, targets.attachmentIDs); err != nil {
100			return err
101		}
102		if err := deleteReactionsByCreatorTx(ctx, tx, userID); err != nil {
103			return err
104		}
105		if err := deleteMemoSharesTx(ctx, tx, userID, memoIDs); err != nil {
106			return err
107		}
108		if err := deleteInboxesByIDsTx(ctx, tx, targets.inboxIDs); err != nil {
109			return err
110		}
111		if err := deleteUserIdentitiesTx(ctx, tx, userID); err != nil {
112			return err
113		}
114		if err := deleteUserSettingsTx(ctx, tx, userID); err != nil {
115			return err
116		}
117		if err := deleteMemoRelationsTx(ctx, tx, memoIDs); err != nil {
118			return err
119		}
120		if err := deleteMemosTx(ctx, tx, memoIDs); err != nil {
121			return err
122		}
123		if err := deleteUserRowTx(ctx, tx, userID); err != nil {
124			return err
125		}
126		return nil
127	}
128	
129	func listDeleteUserMemoTree(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
130		return listDeleteUserMemoTreeRecursive(ctx, tx, userID)
131	}
132	
133	func listDeleteUserMemoTreeRecursive(ctx context.Context, tx *sql.Tx, userID int32) ([]deleteUserMemoRef, error) {
134		rows, err := tx.QueryContext(ctx, `
135			WITH RECURSIVE memo_tree(id, uid) AS (
136				SELECT id, uid
137				FROM memo
138				WHERE creator_id = `+deleteUserPlaceholder(1)+`
139				UNION
140				SELECT child.id, child.uid
141				FROM memo child
142				JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
143				JOIN memo_tree parent ON rel.related_memo_id = parent.id
144			)
145			SELECT id, uid
146			FROM memo_tree
147		`, userID)
148		if err != nil {
149			return nil, err
150		}
151		defer rows.Close()
152	
153		memos := make([]deleteUserMemoRef, 0)
154		for rows.Next() {
155			var memo deleteUserMemoRef
156			if err := rows.Scan(&memo.ID, &memo.UID); err != nil {
157				return nil, err
158			}
159			memos = append(memos, memo)
160		}
161		if err := rows.Err(); err != nil {
162			return nil, err
163		}
164	
165		return memos, nil
166	}
167	
168	func listDeleteUserAttachments(ctx context.Context, tx *sql.Tx, userID int32, memoIDs []int32) ([]*store.Attachment, error) {
169		attachments := make([]*store.Attachment, 0)
170		seen := make(map[int32]struct{})
171		if err := appendDeleteUserAttachments(ctx, tx, `
172			SELECT
173				id,
174				uid,
175				creator_id,
176				memo_id,
177				storage_type,
178				reference,
179				payload
180			FROM attachment
181			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
182			return nil, err
183		}
184	
185		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
186			clause, args := deleteUserInClause(1, batch)
187			if err := appendDeleteUserAttachments(ctx, tx, `
188				SELECT
189					id,
190					uid,
191					creator_id,
192					memo_id,
193					storage_type,
194					reference,
195					payload
196				FROM attachment
197				WHERE memo_id IN `+clause, args, seen, &attachments); err != nil {
198				return nil, err
199			}
200		}
201	
202		return attachments, nil
203	}
204	
205	func appendDeleteUserAttachments(ctx context.Context, tx *sql.Tx, query string, args []any, seen map[int32]struct{}, attachments *[]*store.Attachment) error {
206		rows, err := tx.QueryContext(ctx, query, args...)
207		if err != nil {
208			return err
209		}
210		defer rows.Close()
211	
212		for rows.Next() {
213			attachment := &store.Attachment{}
214			var memoID sql.NullInt32
215			var storageType string
216			var payloadBytes []byte
217			if err := rows.Scan(&attachment.ID, &attachment.UID, &attachment.CreatorID, &memoID, &storageType, &attachment.Reference, &payloadBytes); err != nil {
218				return err
219			}
220			if _, exists := seen[attachment.ID]; exists {
221				continue
222			}
223			seen[attachment.ID] = struct{}{}
224			if memoID.Valid {
225				attachment.MemoID = &memoID.Int32
226			}
227			attachment.StorageType = storepb.AttachmentStorageType(storepb.AttachmentStorageType_value[storageType])
